VALUES ('ji-shuyu', '虞', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '唐叔虞（虞），周成王弟，初封于唐，后改国号晋，为晋国始封君。桐叶封弟典故即指其事。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐叔虞"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, NULL, NULL, '唐叔虞')
