VALUES ('jin-r1', '燮', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，唐叔虞之子，继承晋君之位；传世文献记载简略，具体在位年代失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燮"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, NULL, NULL, '燮')
