VALUES ('jin-r4', '福', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，名福，成侯之子，继位为晋君。北赵晋侯墓地及相关铭文研究为其名号与年代提供线索；传统编年记其卒于前859年，继位年份失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋厉侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '厉侯', NULL, '晋厉侯')
