VALUES ('jin-r5', '宜臼', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋靖侯（宜臼），厉侯之子，前858–前841年在位。在位末年周厉王出奔，史称共和。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋靖侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '靖侯', NULL, '晋靖侯')
