VALUES ('jin-r6', '司徒', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋釐侯（司徒），靖侯之子，前840–前823年在位。西周晋国君主，史书记载有限。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋釐侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '釐侯', NULL, '晋釐侯')
