VALUES ('jin-r7', '籍', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋献侯（籍），釐侯之子，前822–前812年在位。西周晋国世系君主，史书记载有限。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋献侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '献侯', NULL, '晋献侯')
