VALUES ('jin-r8', '费', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋穆侯（费），献侯之子，前811–前785年在位。生太子仇与少子成师，酿成日后曲沃之乱。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋穆侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '穆侯', NULL, '晋穆侯')
