VALUES ('jin-r9', '？', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，穆侯之弟，谥殇叔，个人名失载。穆侯死后取代太子仇为君；前781年文侯仇复位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋殇叔"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '殇叔', NULL, '晋殇叔')
