VALUES ('jin-r10', '仇', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋文侯（仇），穆侯太子，前780–前746年在位。助周平王东迁，周室赐弓矢，晋国始强盛。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋文侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '文侯', NULL, '晋文侯')
