VALUES ('jin-r11', '伯', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋昭侯（伯），文侯之子，前745–前740年在位。筑曲沃城封叔父成师，曲沃坐大之始。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋昭侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '昭侯', NULL, '晋昭侯')
