VALUES ('jin-r12', '成师', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '曲沃桓叔（成师），穆侯少子，曲沃第一代君主，前744–前731年在位。封于曲沃，渐与晋都翼城抗衡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曲沃桓叔"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, NULL, NULL, '曲沃桓叔')
