VALUES ('jin-r13', '平', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋孝侯（平），昭侯之子，前739–前724年在位。被曲沃庄伯派人刺杀，曲沃代翼之争加剧。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋孝侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '孝侯', NULL, '晋孝侯')
