VALUES ('jin-r14', '鱓', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '曲沃庄伯（鱓），桓叔之子，前730–前716年在位。弑孝侯，晋鄂侯出兵反击未成。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曲沃庄伯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, NULL, NULL, '曲沃庄伯')
