VALUES ('jin-r15', '却', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋鄂侯（却），孝侯之弟，前723–前718年在位。连年抵御曲沃庄伯，终为庄伯所弑。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋鄂侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '鄂侯', NULL, '晋鄂侯')
