VALUES ('jin-r16', '光', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋哀侯（光），鄂侯之子，前717–前709年在位。为曲沃武公派人刺杀于宫阙之下。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋哀侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '哀侯', NULL, '晋哀侯')
