VALUES ('jin-r17', '称', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，曲沃庄伯之子，名称。前715年继父为曲沃君，延续曲沃与翼城公室的争位；前678年灭晋侯缗、并有晋地，受周王册命为晋君，前677年去世，子诡诸继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曲沃武公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"},{"label":"《左传·庄公十六年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/zhuang-gong-shi-liu-nian/zhs"}]'::jsonb, '武公', NULL, '曲沃武公')
