VALUES ('jin-r18', '？', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，哀侯之子，史称小子侯，个人名失载。前708年继位，前705年为曲沃武公所杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋小子侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '小子侯', NULL, '晋小子侯')
