VALUES ('jin-r19', '缗', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，名缗，晋侯。曲沃武公攻杀小子侯后，晋人立哀侯之弟于翼，是为缗；前678年为曲沃武公所灭，曲沃并晋。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/缗"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"},{"label":"《左传·庄公十六年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/zhuang-gong-shi-liu-nian/zhs"}]'::jsonb, NULL, NULL, '缗')
