VALUES ('jin-r20', '诡诸', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋献公（诡诸），曲沃武公之子，前676–前651年在位。灭桓庄之族、骊姬之乱，并国十七服国三十八。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋献公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '献公', NULL, '晋献公')
