VALUES ('jin-r21', '夷吾', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋惠公（夷吾），献公之子，骊姬所生，前650–前637年在位。靠秦穆公回国即位，后与秦战于韩失国。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋惠公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '惠公', NULL, '晋惠公')
