VALUES ('jin-r22', '圉', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋怀公（圉），惠公之子，前637年在位。趁重耳在秦欲继位，秦送重耳回国，怀公被杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋怀公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '怀公', NULL, '晋怀公')
