VALUES ('ji-chonger', '重耳', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋文公（重耳），晋献公之子。流亡十九年后即位，城濮之战败楚，践土会盟，列为春秋五霸之一。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋文公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '文公', NULL, '晋文公')
