VALUES ('jin-r24', '欢', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋襄公（欢），文公之子，前627–前621年在位。破秦救周，殽山败秦师，维持晋国霸业。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋襄公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '襄公', NULL, '晋襄公')
