VALUES ('jin-r25', '夷皋', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋灵公（夷皋），襄公之子，前620–前607年在位。荒淫用佞，赵盾屡谏不果，后为赵穿所弑。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋灵公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '灵公', NULL, '晋灵公')
