VALUES ('jin-r26', '黑臀', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋成公（黑臀），文公少母弟，前606–前600年在位。灵公被杀后赵氏拥立，寻讨弑灵公之罪。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋成公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '成公', NULL, '晋成公')
