VALUES ('jin-r27', '据', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋景公（据），成公之子，前599–前581年在位。灭赵氏，邲之战败楚，但六卿势力日盛。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋景公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '景公', NULL, '晋景公')
