VALUES ('jin-r28', '寿曼', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋厉公（寿曼），景公之子，前580–前573年在位。欲集权削六卿，为栾书、中行氏弑杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋厉公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '厉公', NULL, '晋厉公')
