VALUES ('jin-r29', '周', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋悼公（周），襄公曾孙，前572–前558年在位。年少即位却整饬六卿，九合诸侯，晋国复振。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋悼公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '悼公', NULL, '晋悼公')
