VALUES ('jin-r30', '彪', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋平公（彪），悼公之子，前557–前532年在位。会诸侯于平丘，又弭兵于宋，霸业犹存。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋平公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '平公', NULL, '晋平公')
