VALUES ('jin-r31', '夷', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋昭公（夷），平公之子，前531–前526年在位。六卿专权加剧，昭公终死于饥贫。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋昭公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '昭公', NULL, '晋昭公')
