VALUES ('jin-r32', '弃疾', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋顷公（弃疾），昭公之子，前525–前512年在位。诛伯昏咎等大夫，加速六卿兼并。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋顷公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '顷公', NULL, '晋顷公')
