VALUES ('jin-r33', '午', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋定公（午），顷公之子，前511–前475年在位。赵襄子灭智氏，前453年韩赵魏共灭智伯，三家分晋前奏。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋定公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '定公', NULL, '晋定公')
