VALUES ('jin-r34', '凿', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋出公（凿），定公之子，前474–前452年在位。欲讨伐韩赵魏反被逼迁，死于齐。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋出公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '出公', NULL, '晋出公')
