VALUES ('jin-r35', '骄', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋哀公（骄），出公之后，前451–前434年在位。韩赵魏瓜分晋剩余公室土地，君主名存实亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋哀公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '哀公', NULL, '晋哀公')
