VALUES ('jin-r36', '柳', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋幽公（柳），哀公之子，前433–前416年在位。正室地位为赵氏所废，政权益为傀儡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋幽公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '幽公', NULL, '晋幽公')
