VALUES ('jin-r37', '止', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋烈公（止），幽公之后，前415–前389年在位。三家分晋已成定局，烈公仅守附庸之位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋烈公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '烈公', NULL, '晋烈公')
