VALUES ('jin-r38', '颀', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋孝公（颀），烈公之后，前388–前357年在位。魏惠王会诸侯朝天子，孝公仅为陪臣。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋孝公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '孝公', NULL, '晋孝公')
