VALUES ('jin-r39', '俱酒', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋静公（俱酒），孝公之子，前356–前349年在位。三家废晋静公，晋国六卿时代终结。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋静公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, '静公', NULL, '晋静公')
