VALUES ('jin-xi-qi', '奚齐', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋献公与骊姬之子。献公病重时受命由荀息辅佐；献公死后，荀息拥立他继位，前651年在献公丧所被里克杀害，未能逾年。', '[{"label":"《左传·僖公九年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/xi-gong-jiu-nian/zhs"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, NULL, NULL, '奚齐')
