VALUES ('jin-zhuo-zi', '卓子', ARRAY[]::text[], '姬', '晋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '晋献公之子。奚齐被杀后，荀息拥立公子卓以完成献公安葬；前651年周历十一月为里克所杀，荀息亦死。史籍未载其独立谥号。', '[{"label":"《左传·僖公九年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/xi-gong-jiu-nian/zhs"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]'::jsonb, NULL, NULL, '卓子')
